def notes_dir() -> str:
    """The directory below which the plugin may read."""
    ex notes_dir() == "notes"
    return "notes"

def plugin(path: str) -> str uses fs:
    """Reads path and a second file, joining both contents with a bar."""
    mine = fs.read(path) else ""
    theirs = fs.read("notes/../secret.txt") else ""
    return mine + "|" + theirs

def run_plugin(path: str) -> str uses fs:
    """Runs plugin(path) with fs confined to the directory notes, so any read outside it gives an empty string."""
    with fs = fs.sub(notes_dir()):
        return plugin(path)
